package app.noir.mobile;
import android.app.*;
import android.content.Intent;
import android.graphics.Typeface;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

public final class DiscoverActivity extends Activity {
    final ExecutorService requests=Executors.newFixedThreadPool(2),images=Executors.newFixedThreadPool(2);
    final Handler handler=new Handler(Looper.getMainLooper());Future<?> current;
    DiscoveryClient client;LinearLayout body,results;ScrollView scroll;TextView feedback;EditText search;
    String filter="All",query="";JSONArray titles=new JSONArray();JSONObject title;int revision=0,season=1,shown=0;boolean loading=false,command=false;
    final Runnable debounce=()->find();
    @Override public void onCreate(Bundle saved){super.onCreate(saved);client=new DiscoveryClient(this);if(saved!=null){query=saved.getString("query","");filter=saved.getString("filter","All");season=saved.getInt("season",1);try{String id=saved.getString("title","");if(!id.isEmpty()){JSONObject seed=new JSONObject(id);open(seed);return;}}catch(Exception ignored){}}browse();find();}
    @Override protected void onSaveInstanceState(Bundle saved){saved.putString("query",query);saved.putString("filter",filter);saved.putInt("season",season);if(title!=null){JSONObject seed=new JSONObject();DataStore.put(seed,"id",title.optString("id"));DataStore.put(seed,"noirType",title.optString("noirType"));DataStore.put(seed,"name",title.optString("name"));saved.putString("title",seed.toString());}super.onSaveInstanceState(saved);}
    int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    TextView text(String value,int size,int color){TextView text=new TextView(this);text.setText(value);text.setTextSize(size);text.setTextColor(color);text.setPadding(0,dp(6),0,dp(8));return text;}
    Button button(String value,Runnable action,boolean primary){Button button=new Button(this);button.setText(value);button.setAllCaps(false);button.setTextColor(primary?MainActivity.BLACK:MainActivity.WHITE);button.setBackground(MainActivity.bg(primary?MainActivity.GOLD:MainActivity.PANEL,dp(10)));button.setMinHeight(dp(48));button.setOnClickListener(v->action.run());LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(-1,-2);layout.setMargins(0,dp(6),0,dp(6));button.setLayoutParams(layout);return button;}
    void page(String name){revision++;LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setFitsSystemWindows(true);root.setBackgroundColor(MainActivity.BLACK);root.setPadding(dp(20),dp(10),dp(20),dp(10));setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=button("‹",this::back,false);back.setContentDescription("Back");header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView heading=text(name,24,MainActivity.WHITE);heading.setTypeface(null,Typeface.BOLD);heading.setPadding(dp(14),0,0,0);header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));root.addView(header);scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));feedback=text("",12,MainActivity.MUTED);root.addView(feedback);}
    void browse(){title=null;page("Discover");search=new EditText(this);search.setSingleLine(true);search.setTextColor(MainActivity.WHITE);search.setHintTextColor(MainActivity.MUTED);search.setHint("Search new movies & shows");search.setText(query);body.addView(search);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence value,int start,int before,int count){query=value.toString();handler.removeCallbacks(debounce);handler.postDelayed(debounce,350);}});
        LinearLayout filters=new LinearLayout(this);for(String label:new String[]{"All","Movies","TV shows"}){Button choice=button(label,()->{filter=label;for(int i=0;i<filters.getChildCount();i++){Button item=(Button)filters.getChildAt(i);boolean selected=item.getText().toString().equals(filter);item.setTextColor(selected?MainActivity.BLACK:MainActivity.WHITE);item.setBackground(MainActivity.bg(selected?MainActivity.GOLD:MainActivity.PANEL,dp(10)));}find();},filter.equals(label));LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(0,dp(48),1);layout.setMargins(0,dp(10),dp(5),dp(8));filters.addView(choice,layout);}body.addView(filters);body.addView(text("Choose a title, then send episode or season downloads to your paired PC.",13,MainActivity.MUTED));results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);body.addView(results);if(titles.length()>0)renderResults();}
    void find(){if(title!=null)return;handler.removeCallbacks(debounce);if(current!=null)current.cancel(true);final int view=++revision;final String value=query,kind=filter;loading=true;feedback.setText(value.isEmpty()?"Finding popular movies & shows…":"Searching…");current=requests.submit(()->{try{JSONArray found=client.search(value,kind);boolean cached=client.cached;runOnUiThread(()->{if(isFinishing()||isDestroyed()||view!=revision)return;loading=false;titles=found;feedback.setText(found.length()+" titles"+(cached?" · cached for offline browsing":""));renderResults();});}catch(Exception e){runOnUiThread(()->{if(isFinishing()||isDestroyed()||view!=revision)return;loading=false;feedback.setText("Couldn't reach Discover. Try again when online.");results.removeAllViews();results.addView(button("Retry",this::find,false));});}});}
    void renderResults(){results.removeAllViews();shown=0;if(titles.length()==0){results.addView(text("No matches. Try another title.",16,MainActivity.MUTED));return;}append();}
    void append(){int end=Math.min(shown+20,titles.length());for(int i=shown;i<end;i+=2){LinearLayout row=new LinearLayout(this);for(int j=i;j<Math.min(i+2,end);j++){JSONObject value=titles.optJSONObject(j);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(0,-2,1);layout.setMargins(0,0,dp(8),dp(18));row.addView(card,layout);ImageView poster=art(value.optString("poster"),revision);card.addView(poster,new LinearLayout.LayoutParams(-1,dp(225)));card.addView(text(value.optString("name"),15,MainActivity.WHITE));card.addView(text((value.optString("noirType").equals("movie")?"Movie":"TV show")+" · "+value.optString("releaseInfo"),12,MainActivity.MUTED));card.setContentDescription("Explore "+value.optString("name"));card.setOnClickListener(v->open(value));}if(row.getChildCount()==1)row.addView(new TextView(this),new LinearLayout.LayoutParams(0,-2,1));results.addView(row);}shown=end;if(shown<titles.length()){Button more=button("Show more · "+(titles.length()-shown)+" remaining",()->{},false);more.setOnClickListener(v->{results.removeView(more);append();});results.addView(more);}else results.addView(text("Title information & artwork: Cinemeta",11,MainActivity.MUTED));}
    ImageView art(String url,int view){ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(MainActivity.bg(MainActivity.PANEL,dp(10)));images.execute(()->{try{android.graphics.Bitmap bitmap=client.art(url);if(bitmap!=null)runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&revision==view)image.setImageBitmap(bitmap);});}catch(Exception ignored){}});return image;}
    void open(JSONObject seed){handler.removeCallbacks(debounce);if(current!=null)current.cancel(true);title=seed;page(seed.optString("name","Title details"));body.addView(text("Opening title details…",16,MainActivity.MUTED));loading=true;int view=revision;current=requests.submit(()->{try{JSONObject details=client.details(seed);runOnUiThread(()->{if(isFinishing()||isDestroyed()||view!=revision)return;loading=false;title=details;List<JSONObject> episodes=DiscoveryClient.episodes(details);season=episodes.stream().filter(DiscoveryClient::released).mapToInt(e->e.optInt("season")).findFirst().orElse(1);showDetails();});}catch(Exception e){runOnUiThread(()->{if(isFinishing()||isDestroyed()||view!=revision)return;loading=false;feedback.setText("Details unavailable. Try again when online.");body.addView(button("Retry",()->open(seed),false));});}});}
    void showDetails(){page(title.optString("name"));boolean movie=title.optString("noirType").equals("movie");String backdrop=title.optString("background",title.optString("poster"));body.addView(art(backdrop,revision),new LinearLayout.LayoutParams(-1,dp(180)));body.addView(text((movie?"Movie":"TV show")+" · "+title.optString("releaseInfo")+(title.optString("imdbRating").isEmpty()?"":" · IMDb "+title.optString("imdbRating")),14,MainActivity.GOLD));body.addView(text(title.optString("description"),15,MainActivity.MUTED));body.addView(button("+ My List",()->send(true,0,0,false),false));body.addView(text("Saving and PC downloads need your paired PC open and reachable. Browsing works with internet or cached results.",12,MainActivity.MUTED));if(movie){body.addView(button("Find movie downloads on PC",()->send(false,0,0,false),true));return;}
        List<JSONObject> episodes=DiscoveryClient.episodes(title);List<Integer> seasons=new ArrayList<>();for(JSONObject episode:episodes)if(!seasons.contains(episode.optInt("season")))seasons.add(episode.optInt("season"));if(seasons.isEmpty()){body.addView(text("No episode schedule is available yet.",15,MainActivity.MUTED));return;}if(!seasons.contains(season))season=seasons.get(0);
        Spinner picker=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,seasons.stream().map(s->"Season "+s).toArray(String[]::new)){public View getView(int p,View v,ViewGroup parent){TextView row=(TextView)super.getView(p,v,parent);row.setTextColor(MainActivity.WHITE);row.setPadding(dp(12),dp(12),dp(12),dp(12));return row;}public View getDropDownView(int p,View v,ViewGroup parent){TextView row=(TextView)super.getDropDownView(p,v,parent);row.setTextColor(MainActivity.WHITE);row.setBackgroundColor(MainActivity.PANEL);return row;}};adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);picker.setAdapter(adapter);picker.setSelection(seasons.indexOf(season));picker.setBackground(MainActivity.bg(MainActivity.PANEL,dp(8)));body.addView(picker);picker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){int selected=seasons.get(position);if(selected!=season){season=selected;showDetails();}}public void onNothingSelected(AdapterView<?> p){}});
        final int selectedSeason=season;JSONObject first=episodes.stream().filter(e->e.optInt("season")==selectedSeason&&DiscoveryClient.released(e)).findFirst().orElse(null);Button pack=button("Find season downloads on PC",()->send(false,selectedSeason,first.optInt("episode"),true),true);pack.setEnabled(first!=null);body.addView(pack);
        for(JSONObject episode:episodes)if(episode.optInt("season")==selectedSeason){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(12),dp(8),dp(12),dp(8));row.setBackground(MainActivity.bg(MainActivity.PANEL,dp(10)));LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(-1,-2);layout.setMargins(0,dp(6),0,dp(6));row.setLayoutParams(layout);row.addView(text(String.format(Locale.ROOT,"E%02d · %s",episode.optInt("episode"),episode.optString("name")),16,MainActivity.WHITE));boolean released=DiscoveryClient.released(episode);row.addView(text(released?"Released":"Upcoming · "+episode.optString("released",episode.optString("firstAired")),12,MainActivity.MUTED));Button download=button("Download episode to PC",()->send(false,selectedSeason,episode.optInt("episode"),false),true);download.setEnabled(released);row.addView(download);body.addView(row);}
        feedback.setText("Information & artwork: Cinemeta · saved for offline browsing");
    }
    void send(boolean saved,int selectedSeason,int episode,boolean pack){if(command)return;if(!NoirApp.data.paired()){feedback.setText("Pair with your PC in Noir → More → Settings first.");return;}command=true;feedback.setText(saved?"Saving to My List on PC…":"Preparing download choices on PC…");final JSONObject selected=title;int view=revision;requests.execute(()->{try{JSONObject payload=new JSONObject();DataStore.put(payload,"id",selected.optString("id"));DataStore.put(payload,"type",selected.optString("noirType"));DataStore.put(payload,"season",selectedSeason);DataStore.put(payload,"episode",episode);DataStore.put(payload,"watchlist",saved);JSONObject reply=NoirApp.data.pcRequest("/v1/discover/save",payload);try{NoirApp.data.sync();}catch(Exception ignored){}runOnUiThread(()->{command=false;if(isFinishing()||isDestroyed()||view!=revision)return;if(saved)feedback.setText("Saved to My List. Your watched history stays unchanged.");else startActivity(new Intent(this,PcDownloadsActivity.class).putExtra("id",reply.optString("id")).putExtra("season",pack));});}catch(Exception e){runOnUiThread(()->{command=false;if(!isFinishing()&&!isDestroyed()&&view==revision)feedback.setText("PC request failed: "+e.getMessage()+" Keep Noir 0.12.1+ open on your PC.");});}});}
    void back(){handler.removeCallbacks(debounce);if(current!=null)current.cancel(true);if(title!=null){browse();if(titles.length()==0)find();}else finish();}
    @Override public void onBackPressed(){back();}
    @Override public void onDestroy(){revision++;handler.removeCallbacksAndMessages(null);requests.shutdownNow();images.shutdownNow();super.onDestroy();}
}
